 counts=Counter(x['classification'] for x in paired);families={}
 for f in sorted({x['family'] for x in paired}):
  rs=[x for x in paired if x['family']==f];bc=sum(x['base_score'] for x in rs);pc=sum(x['pilot_score'] for x in rs);families[f]={'N':len(rs),'base_correct':bc,'pilot_correct':pc,'base_accuracy':bc/len(rs),'pilot_accuracy':pc/len(rs),'delta':(pc-bc)/len(rs),'WIN':sum(x['classification']=='WIN' for x in rs),'REGRESSION':sum(x['classification']=='REGRESSION' for x in rs),'BOTH_PASS':sum(x['classification']=='BOTH_PASS' for x in rs),'BOTH_FAIL':sum(x['classification']=='BOTH_FAIL' for x in rs)}
 overall={'N':len(paired),'base_correct':sum(x['base_score'] for x in paired),'pilot_correct':sum(x['pilot_score'] for x in paired)};overall.update({'base_accuracy':overall['base_correct']/len(paired),'pilot_accuracy':overall['pilot_correct']/len(paired),'delta':(overall['pilot_correct']-overall['base_correct'])/len(paired),**counts})
 train=jl(PKG/'data/training/train.jsonl');val=jl(PKG/'data/training/validation.jsonl');src=Counter(x.get('metadata',{}).get('source','UNKNOWN') for x in train);tf=Counter(x.get('metadata',{}).get('task_family','UNKNOWN') for x in train);data_dist={'acquisition_v1_1':{'downloaded':805,'deduplicated':680,'oasst1':181,'mathinstruct':299,'gemo':200,'programmatic_math':200,'programmatic_math_ratio':200/680},'topup_v1_final':{'total':841,'programmatic_math':300,'programmatic_math_ratio':300/841},'actual_input_pool':841,'actual_train':len(train),'actual_validation':len(val),'train_task_family_distribution':tf,'train_source_distribution':src,'mathematical_reasoning_train_ratio':tf['MATHEMATICAL_REASONING']/len(train),'all_math_family_train_ratio':sum(tf[x] for x in ('MATHEMATICAL_REASONING','LINEAR_ALGEBRA','CALCULUS','PROBABILITY_STATISTICS'))/len(train),'effective_sampling_target_math_reasoning_ratio':0.35,'notes':['The 680 figure belongs to acquisition V1.1; Pilot V0 actually trained on 757 rows split from the 841-row V1.2 pool.','V1.2 programmatic math is 300/841 (35.67%), higher than the earlier 200/680 (29.41%).','Effective sampling targets 35% MATHEMATICAL_REASONING; family/source labels show imbalance but do not prove causality.','BASIC_CODE has only 8 train rows and BASIC_SCIENCE only 1; spot checks also show family-label quality concerns.']}
 reason=Counter(x['primary_reason'] for x in regs); top=[k for k,v in reason.most_common(3)]; net=overall['delta']; forgetting='NO_CLEAR_FORGETTING' if net>=0 and len(regs)<=len(wins) else 'LOCALIZED_FORGETTING' if net>-0.10 else 'MODERATE_FORGETTING' if net>-0.25 else 'SEVERE_FORGETTING'
 training_diagnosis={'verdict':'LIKELY_DATA_ISSUE','learning_rate':1e-4,'epochs':2,'effective_batch_size':16,'lora_r':16,'lora_alpha':32,'lora_dropout':0.05,'target_modules':['q_proj','k_proj','v_proj','o_proj'],'max_seq_length':2048,'bf16':True,'loss_masking':'ASSISTANT_COMPLETION_ONLY (audit PASS)','chat_template':'Qwen chat template; tokenizer revision frozen','eos_handling':'terminal im_end supervised','packing':'NOT_CONFIGURED_IN_REVIEWED_CONFIG','warmup':'NOT_CONFIGURED_IN_REVIEWED_CONFIG','weight_decay':'NOT_CONFIGURED_IN_REVIEWED_CONFIG','evidence':'No direct sign that intensity caused the three localized regressions; composition imbalance and label/coverage quality are the stronger evidence.','recommendation':'Keep all training parameters fixed for the first Pilot V1 composition-only attribution run.'}
 rec={'increase_general_replay':'YES_WITH_TARGETED_REBALANCING','priorities':[{'capability':'instruction following with value fidelity / transformations','priority':'HIGH','additional_cases':'100-150'},{'capability':'general reasoning with deterministic gold','priority':'HIGH','additional_cases':'80-120'},{'capability':'general QA, basic science, reading comprehension','priority':'HIGH','additional_cases':'100-150'},{'capability':'writing and multilingual instruction','priority':'MEDIUM','additional_cases':'50-80'},{'capability':'safe functional coding diversity','priority':'LOW','additional_cases':'20-40 maintenance replay'},{'capability':'non-programmatic math diversity','priority':'LOW','additional_cases':'20-30 while reducing programmatic repetition'}],'pilot_v1_general_replay_total':'1100-1350 after quality filtering and math downsampling','target_distribution_percent':{'instruction_following_value_fidelity':25,'general_qa_basic_science_reading':22,'general_reasoning':20,'writing_multilingual':12,'coding':8,'non_programmatic_math':8,'linear_algebra_calculus_probability':5},'programmatic_math_cap':'<=10-12% of general replay','problem_source_verdict':'LIKELY_DATA_ISSUE','pilot_v1_freeze':['base model','tokenizer','chat template','LoRA r/alpha/dropout/target modules','General V0.1 evaluation','evaluator','seed 42','deterministic decoding','learning rate 1e-4 for first attribution run'],'pilot_v1_change':['general replay composition','family sampling ratios'],'optional_second_variable':'Only if a composition-only run still regresses: lower learning rate modestly from 1e-4 in a separate experiment.','predefined_gate':'CONDITIONAL_GO','data_acquisition_decision':'READY_FOR_TARGETED_DATA_ACQUISITION'}
 audit={'package':str(PKG),'sets':{'general_v0_1':{'base_count':len(base),'pilot_count':len(pilot),'paired_count':len(ids),'base_unique_ids':len(bm),'pilot_unique_ids':len(pm),'missing_in_base':sorted(set(pm)-set(bm)),'missing_in_pilot':sorted(set(bm)-set(pm)),'comparable_fields':['case_id','family','prompt','gold','raw_output','parsed_output','score','scorer_type','reason','latency_ms','output_token_count'],'score_definition':'Binary 0/1 from frozen deterministic machine scorer; pass threshold is the native score, not an invented threshold.'}},'other_assets':{'campus_per_case_present':(PKG/'results/base/campus_per_case.jsonl').exists() and (PKG/'results/pilot_v0/campus_per_case.jsonl').exists(),'general_comparison_present':(PKG/'results/comparison/general_comparison.json').exists(),'training_config_present':(ROOT/'experiments/fine_tuning_pilot_v0_upload/config/training_config.yaml').exists()}}
 dumpjl(OUT/'paired_cases.jsonl',paired);dumpjl(OUT/'regressions.jsonl',regs);dumpjl(OUT/'wins.jsonl',wins);dumpj(OUT/'input_audit.json',audit);dumpj(OUT/'category_metrics.json',{'overall':overall,'families':families});dumpj(OUT/'regression_reason_distribution.json',reason);dumpj(OUT/'training_data_distribution.json',data_dist);dumpj(OUT/'training_config_diagnosis.json',training_diagnosis);dumpj(OUT/'pilot_v1_data_recommendation.json',rec)
 report=f'''# Fine-tuning Pilot V0 Failure Analysis V1\n\n## Executive conclusion\n\nPilot V0 changed General accuracy from {overall['base_accuracy']:.1%} to {overall['pilot_accuracy']:.1%} (delta {overall['delta']:+.1%}). There were {counts['WIN']} wins and {counts['REGRESSION']} regressions. Forgetting assessment: `{forgetting}`. The gain is concentrated in strict format and constraint compliance, not broad reasoning: General Reasoning, Linear Algebra, Mathematical Reasoning, and Probability remain 0% for both models.\n\n## Paired results\n\n| Metric | Base | Pilot V0 | Delta |\n|---|---:|---:|---:|\n| Correct | {overall['base_correct']}/100 | {overall['pilot_correct']}/100 | {overall['pilot_correct']-overall['base_correct']:+d} |\n| Accuracy | {overall['base_accuracy']:.1%} | {overall['pilot_accuracy']:.1%} | {overall['delta']:+.1%} |\n\nWIN {counts['WIN']}; REGRESSION {counts['REGRESSION']}; BOTH_PASS {counts['BOTH_PASS']}; BOTH_FAIL {counts['BOTH_FAIL']}.\n\n## Main regression profile\n\nTwo instruction-value fidelity regressions and one basic-science factual regression were observed. No third regression category exists in this run. Detailed evidence is preserved in `regressions.jsonl`.\n\n## Data diagnosis\n\nThe 680-row figure is acquisition V1.1, not the final Pilot input. V1.2 has 841 rows, including 300 programmatic-math rows (35.67%); Pilot used a 757/84 split. Mathematical reasoning is {data_dist['mathematical_reasoning_train_ratio']:.1%} of train rows and all math families are {data_dist['all_math_family_train_ratio']:.1%}. Code ({tf['BASIC_CODE']} rows), science ({tf['BASIC_SCIENCE']}), and non-math reasoning ({tf['GENERAL_REASONING']}) are sparse. This imbalance is a `POSSIBLE_CAUSE`, not proof of causality.\n\n## Training diagnosis\n\nVerdict: `LIKELY_DATA_ISSUE`. Two epochs, LR 1e-4, effective batch 16, LoRA r=16/alpha=32, assistant-completion-only loss, and q/k/v/o targeting provide no direct evidence of excessive intensity. Keep them fixed for a composition-only V1 attribution run. If regression persists, test a modest LR reduction separately.\n\n## Pilot V1 recommendation\n\nUse targeted rebalancing to 1100-1350 General replay cases. Prioritize instruction value fidelity, deterministic general reasoning, and QA/science/reading. Maintain code with a smaller diverse slice, add non-programmatic math diversity, and cap programmatic math near 10-12%. Predefined gate: `CONDITIONAL_GO`: no overall General regression, fewer regressions than V0, no severe family collapse, and target/Campus behavior maintained.\n\n## Acquisition decision\n\n`READY_FOR_TARGETED_DATA_ACQUISITION`\n'''
